import wiki from './equestria-wiki.json';
import { escape as e } from './icons';

// Generated by scripts/export-equestria-wiki.mjs from the game's own data.
interface WikiSection { heading: string; text?: string; columns?: string[]; rows?: string[][] }
interface WikiPage { id: string; title: string; sections: WikiSection[] }
const pages = wiki.pages as WikiPage[];
export const harmonyElements = wiki.elements;
let current = pages[0].id;

export function selectWikiPage(id: string) { if (pages.some(p => p.id === id)) current = id; }

export function renderWiki(tabs: string) {
  const page = pages.find(p => p.id === current) || pages[0];
  const section = (s: WikiSection) => `<section class="wiki-section"><h3>${e(s.heading)}</h3>${s.text ? `<p>${e(s.text)}</p>` : ''}${s.rows ? `<div class="wiki-table"><table>${s.columns ? `<thead><tr>${s.columns.map(c => `<th>${e(c)}</th>`).join('')}</tr></thead>` : ''}<tbody>${s.rows.map(r => `<tr>${r.map(c => `<td>${e(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>` : ''}</section>`;
  return `${tabs}<div class="page-heading"><div><p class="eyebrow">EVERYTHING ABOUT THE KINGDOM</p><h1>Equestria wiki</h1><p class="subheading">Ponies, flight, friendship and treasure, straight from the game's own data.</p></div></div>
  <div class="wiki-layout"><nav class="wiki-nav" aria-label="Wiki pages">${pages.map(p => `<button class="${p.id === page.id ? 'selected' : ''}" data-action="wiki-page" data-page="${p.id}" aria-current="${p.id === page.id}">${e(p.title)}</button>`).join('')}</nav>
  <article class="wiki-page"><h2>${e(page.title)}</h2>${page.sections.map(section).join('')}</article></div>`;
}
